INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('1ab9344c-ec6e-5b61-9baa-530e0805c4d5','TEXT','Proofreading passage PB','The students checked the afula before the activity began. Our group recorded the agache in the class notebook. The students checked the agaches before the activity began. Our group recorded the again in the class notebook. The students checked the against before the activity began. Our group recorded the agamemnon in the class notebook. The students checked the agana before the activity began. Our group recorded the aganbegyan in the class notebook. The students checked the agans before the activity began.',NULL,NULL,NULL,5,'SPELLING','PUBLISHED',NULL);
